positions=[m.start() for m in re.finditer(r'"__typename":"IssueComment"', text)]
for i,pos in enumerate(positions):
    segment=text[pos: positions[i+1] if i+1<len(positions) else pos+30000]
    fields={}
    for pat,name in [(r'"databaseId":(\d+)','databaseId'),(r'"author":\{"__typename":"User","login":"([^"]+)"','author'),(r'"createdAt":"([^"]+)"','createdAt'),(r'"minimizedReason":([^,}]+)','minimizedReason'),(r'"body":"((?:\\.|[^"\\])*)"','body')]:
        m=re.search(pat, segment)
        if m:
            val=m.group(1)
            if name=='body': val=json.loads('"'+val+'"')
            fields[name]=val
    print('\n=== COMMENT', i+1, '===')
    for k,v in fields.items():
        print(f'{k}: {v}')
